public class Cap {
    public static String capitalise(String s) {
        return s;
    }
}

exercises.solution:
public class Cap {
    public static String capitalise(String s) {
        s = s.trim();
        if (s.isEmpty()) return "";
        return s.substring(0, 1).toUpperCase() + s.substring(1).toLowerCase();
    }
}

