public class Initials {
    public static String initials(String fullName) {
        return "";
    }
}

exercises.solution:
public class Initials {
    public static String initials(String fullName) {
        StringBuilder sb = new StringBuilder();
        for (String p : fullName.trim().split("\\s+")) {
            if (!p.isEmpty()) sb.append(Character.toUpperCase(p.charAt(0))).append(".");
        }
        return sb.toString();
    }
}
